#include <iostream>
#include <vector>
using namespace std;

int findPivot(vector<int>& nums) {
  // 左索引的初始值为 0
  int left = 0;
  // 右索引的初始值是数组中元素的数量
  int right = nums.size();
  // left + 1 >= right 将完成 while 循环
  while (left + 1 < right) {
    int mid = (right + left) / 2;

    if (nums[mid - 1] > nums[mid]) {
      // mid 是要回答的索引
      return mid;
    } else if (nums[left] < nums[mid]) {
      // 在数组的左半部分搜索是没有意义的
      left = mid;
    } else {
      // 在数组的右半部分搜索没有意义
      right = mid;
    }
  }
  // 左边是答案
  return left;
}

int ascendingBinarySearch(vector<int>& nums, int left, int right, int target) {
  while (left + 1 < right) {
    int mid = (right + left) / 2;

    if (nums[mid] == target) {
      return mid;
    } else if (nums[mid] < target) {
      left = mid;
    } else {
      right = mid;
    }
  }

  if (nums[left] == target) {
    return left;
  }

  if (right < nums.size() && nums[right] == target) {
    return right;
  }

  return -1;
}

int search(vector<int>& nums, int target) {
  int pivot = findPivot(nums);
  int indexInLeftPart = ascendingBinarySearch(nums, 0, pivot, target);

  if (indexInLeftPart != -1) {
    return indexInLeftPart;
  }

  int indexInRightPart = ascendingBinarySearch(nums, pivot, nums.size(), target); 

  if (indexInRightPart != -1) {
    return indexInRightPart;
  }

  return -1;
}

int main() {
  vector<int> nums = {-5, 1, 2, 3, 4, 5, -8, -7, -6};

  cout << "Index of 5 is ---> "  << search(nums, 5) << endl;
  cout << "Index of 6 is ---> "  << search(nums, 6) << endl;
  cout << "Index of -5 is ---> "  << search(nums, -5) << endl;
  cout << "Index of -6 is ---> "  << search(nums, -6) << endl;

  return 0;
}

