#include <iostream>
#include <vector>
using namespace std;

int singleNonDuplicate(vector<int>& nums) {
  // 左索引的初始值为 0
  int left = 0;
  // 右索引的初始值是数组中元素的数量
  int right = nums.size();
  // left + 1 >= right 将完成 while 循环
  while (left + 1 < right) {
    int mid = (right + left) / 2;

    if (nums[mid] != nums[mid - 1] && (1 + mid == nums.size() || nums[mid] != nums[mid + 1])) {
      // 中间索引上的元素就是答案
      return nums[mid];
    } else if (((mid % 2) != 0 && nums[mid] == nums[mid - 1]) || ((mid % 2) == 0 && nums[mid] == nums[mid + 1])) {
      // 在数组的左半部分搜索是没有意义的
      left = mid;
    } else {
      // 在数组的右半部分搜索没有意义
      right = mid;
    }
  }
  // 左边索引的元素就是答案
  return nums[left];
}

int main() {
  vector<int> nums1 = {1,1,2,3,3,4,4,8,8};
  vector<int> nums2 = {3,3,7,7,10,11,11};
  vector<int> nums3 = {1,1,2,2,3};
  vector<int> nums4 = {1};

  cout << "The single element is ---> "  << singleNonDuplicate(nums1) << endl;
  cout << "The single element is ---> "  << singleNonDuplicate(nums2) << endl;
  cout << "The single element is ---> "  << singleNonDuplicate(nums3) << endl;
  cout << "The single element is ---> "  << singleNonDuplicate(nums4) << endl;

  return 0;
}

