class Solution {
  int findBitonicPoint(int[] nums) {
    // 左索引的初始值为 0
    int left = 0;
    // 右索引的初始值是数组中元素的数量
    int right = nums.length;
    // left + 1 >= right 将完成 while 循环
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid - 1] < nums[mid] && nums[mid + 1] < nums[mid]) {
        // mid 是要回答的索引
        return mid;
      } else if (nums[mid - 1] < nums[mid]) {
        // 在数组的左半部分搜索是没有意义的
        left = mid;
      } else {
        // 在数组的右半部分搜索没有意义
        right = mid;
      }
    }
    // 左边是答案
    return left;
  }

  int ascendingBinarySearch(int[] nums, int left, int right, int target) {
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid] == target) {
        return mid;
      } else if (nums[mid] < target) {
        left = mid;
      } else {
        right = mid;
      }
    }

    if (nums[left] == target) {
      return left;
    }

    if (nums[right] == target) {
      return right;
    }

    return -1;
  } 

  int descendingBinarySearch(int[] nums, int left, int right, int target) {
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid] == target) {
        return mid;
      } else if (nums[mid] > target) {
        left = mid;
      } else {
        right = mid;
      }
    }

    if (nums[left] == target) {
      return left;
    }

    if (nums[right] == target) {
      return right;
    }

    return -1;
  }

  int searchInBitonicArray(int[] nums, int target) {
    int bitonicPoint = findBitonicPoint(nums);
    int indexInLeftPart = ascendingBinarySearch(nums, 0, bitonicPoint, target);

    if (-1 != indexInLeftPart) {
      return indexInLeftPart;
    }

    int indexInRightPart = descendingBinarySearch(nums, bitonicPoint + 1, nums.length, target); 

    if (-1 != indexInRightPart) {
      return indexInRightPart;
    }

    return -1;
  }

  public static void main(String[] args) {
    Solution sol = new Solution();
    int[] nums = new int[] {-8, 1, 2, 3, 4, 5, -2, -3, -9};

    System.out.println("Index of 5 is ---> " + sol.searchInBitonicArray(nums, 5));
    System.out.println("Index of 1 is ---> " + sol.searchInBitonicArray(nums, 1));
    System.out.println("Index of -9 is ---> " + sol.searchInBitonicArray(nums, -9));
    System.out.println("Index of -1 is ---> " + sol.searchInBitonicArray(nums, -1));
  }
}

