class Solution {
  int findCount(int[] nums, int target) {
    int left = binarySearch(nums, target, true);

    if (left < 0) {
      return -1;
    }

    int right = binarySearch(nums, target, false);

    return right - left + 1;
  }

  int binarySearch(int[] nums, int target, boolean leftmost) {
    // 左索引的初始值为 0
    int left = 0;
    // 右索引的初始值是数组中元素的数量
    int right = nums.length;
    // left + 1 >= right 将完成 while 循环
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid] == target) {
        if (leftmost) {
          right = mid;
        } else {
          left = mid;
        }
      } else if (nums[mid] < target) {
        // 在数组的左半部分搜索是没有意义的
        left = mid;
      } else {
        // 在数组的右半部分搜索没有意义
        right = mid;
      }
    }
    // left 可以是答案的索引
    if (nums[left] == target) {
      return left;
    }
    // right 可能是寻找的索引
    if (right < nums.length && nums[right] == target) {
      return right;
    }
    // 数组中没有目标
    return -1;
  }

  public static void main(String[] args) {
    Solution sol = new Solution();
    int[] nums = new int[] {1, 5, 5, 5, 11, 11, 15, 19, 19};

    System.out.println("The number of occurrences of 5 is ---> " + sol.findCount(nums, 5));
    System.out.println("The number of occurrences of 20 is ---> " + sol.findCount(nums, 20));
    System.out.println("The number of occurrences of 1 is ---> " + sol.findCount(nums, 1));
    System.out.println("The number of occurrences of 19 is ---> " + sol.findCount(nums, 19));
  }
}

