class Solution {
  int sqrt(int a) {
    if (a < 2) {
      return a;
    }
    // left 的初始值为 0
    int left = 0;
    // right 的初始值是数组大小
    int right = a;
    // left + 1 >= right 将完成 while 循环
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (mid * mid == a) {
        // mid 是答案
        return mid;
      } else if (mid * mid < a) {
        // 在小于mid的数字中搜索没有意义
        left = mid;
      } else {
        // 在大于mid的数字中中搜索没有意义
        right = mid;
      }
    }
    // 左边是答案
    return left;
  }

  public static void main(String[] args) {
    Solution sol = new Solution();

    System.out.println("The square root of 11 is ---> " + sol.sqrt(11));
    System.out.println("The square root of 9 is ---> " + sol.sqrt(9));
  }
